		this._childRenderResult = null;
		this._childParentVNode = null;
		this._matchedOldVNode = null;
		this._matchingOldChildren = null;
		this._matchingOldLength = 0;
		this._placementParent = null;
		this._placementOldDom = null;
		this._placementFirstDom = null;
		this._placementExcess = null;
		this._lifecycleComponent = null;
		this._lifecycleContext = null;
		this._lifecycleQueue = null;
		this._lifecycleIsNew = false;
		this._propDom = null;
		this._propBag = null;
		this._propSvg = false;
		this._teardownTarget = null;
		this._refList = null;
		this._pendingRenders = [];
		this._pendingRenderCount = 0;
		this._lastDebounce = undefined;
		this._lastCreatedVNode = null;
		this._pointerVNode = null;
		this._deferFlush =
			typeof Promise == 'function'
				? Promise.prototype.then.bind(Promise.resolve())
				: setTimeout;
	}

	_captureRendererState() {
		return {
			_normalizedChild: this._normalizedChild,
			_childRenderResult: this._childRenderResult,
			_childParentVNode: this._childParentVNode,
			_matchedOldVNode: this._matchedOldVNode,
			_matchingOldChildren: this._matchingOldChildren,
			_matchingOldLength: this._matchingOldLength,
			_placementParent: this._placementParent,
			_placementOldDom: this._placementOldDom,
			_placementFirstDom: this._placementFirstDom,
			_placementExcess: this._placementExcess,
			_lifecycleComponent: this._lifecycleComponent,
			_lifecycleContext: this._lifecycleContext,
			_lifecycleQueue: this._lifecycleQueue,
			_lifecycleIsNew: this._lifecycleIsNew,
			_propDom: this._propDom,
			_propBag: this._propBag,
			_propSvg: this._propSvg,
			_teardownTarget: this._teardownTarget,
			_refList: this._refList,
			_lastCreatedVNode: this._lastCreatedVNode,
			_pointerVNode: this._pointerVNode
		};
	}

	_restoreRendererState(snapshot) {
		this._normalizedChild = snapshot._normalizedChild;
		this._childRenderResult = snapshot._childRenderResult;
		this._childParentVNode = snapshot._childParentVNode;
		this._matchedOldVNode = snapshot._matchedOldVNode;
		this._matchingOldChildren = snapshot._matchingOldChildren;
		this._matchingOldLength = snapshot._matchingOldLength;
		this._placementParent = snapshot._placementParent;
		this._placementOldDom = snapshot._placementOldDom;
		this._placementFirstDom = snapshot._placementFirstDom;
		this._placementExcess = snapshot._placementExcess;
		this._lifecycleComponent = snapshot._lifecycleComponent;
		this._lifecycleContext = snapshot._lifecycleContext;
		this._lifecycleQueue = snapshot._lifecycleQueue;
		this._lifecycleIsNew = snapshot._lifecycleIsNew;
		this._propDom = snapshot._propDom;
		this._propBag = snapshot._propBag;
		this._propSvg = snapshot._propSvg;
		this._teardownTarget = snapshot._teardownTarget;
		this._refList = snapshot._refList;
		this._lastCreatedVNode = snapshot._lastCreatedVNode;
		this._pointerVNode = snapshot._pointerVNode;
	}

	createVNode(type, props, key, ref, original) {
		const vnode = {
			type,
			props,
			key,
			ref,
			_children: null,
			_parent: null,
			_depth: 0,
			_dom: null,
			_nextDom: undefined,
			_component: null,
			_hydrating: null,
			constructor: undefined,
