	}

	isEmptyNormalizedChild() {
		const childVNode = this._normalizedChild;
		return childVNode == null || typeof childVNode == 'boolean';
	}

	isTextLikeChild() {
		const childVNode = this._normalizedChild;
		return typeof childVNode == 'string' || typeof childVNode == 'number';
	}

	isArrayChild() {
