	}

	adoptExistingChild() {
		this._normalizedChild = this._normalizedChild;
	}

	storeNormalizedChild(i) {
		this._childParentVNode._children[i] = this._normalizedChild;
	}

	attachChildParent() {
		const childVNode = this._normalizedChild;
		const newParentVNode = this._childParentVNode;
		childVNode._parent = newParentVNode;
		childVNode._depth = newParentVNode._depth + 1;
	}

	toChildArray(children, out) {
		this._normalizedChild = children;
		out = out || [];
		if (children == null || typeof children == 'boolean') {
		} else if (Array.isArray(children)) {
			children.some(child => {
				this.toChildArray(child, out);
